    if (inner.charAt(0) === '\r' && inner.charAt(1) === '\n') inner = inner.slice(2);
    else if (inner.charAt(0) === '\n') inner = inner.slice(1);
    if (inner.length >= 2 && inner.slice(-2) === '\r\n') inner = inner.slice(0, -2);
    else if (inner.length >= 1 && inner.slice(-1) === '\n') inner = inner.slice(0, -1);
  }
  var head = t.slice(0, i);
  var tail = t.slice(j + NARR_USR_CLOSE.length);
  if (!inner) {
    head = head.replace(/[ \t]+$/, '');
    tail = tail.replace(/^[ \t\r\n]+/, '');
    if (!tail) return head.replace(/[\s]+$/, '');
    return head + (head ? '\n\n' : '') + tail;
  }
  return head + inner + tail;
}

function narrUnwrapUser(s) {
  var t = String(s == null ? '' : s);
  for (var k = 0; k < 8; k++) {
    var n = narrUnwrapUserOnce(t);
    if (n === t) break;
    t = n;
  }
  return t;
}

/* 彻底剥离 AR-NAR 与 AR-USR（对外保持 narrStrip 接口兼容） */
function narrStrip(s) {
  var t = String(s == null ? '' : s);
  for (var k = 0; k < 8; k++) {
    var n = narrStripNarOnce(t);
    if (n === t) break;
    t = n;
  }
  t = narrUnwrapUser(t);
  return t;
}

/* 构造三明治贴脸包裹：depth=0 用全量身份解耦+RLHF重导流；depth=1~2 用轻量意图降格包壳 */
function narrWrapUserText(rawText, isLatest, lethal) {
  var raw = String(rawText == null ? '' : rawText);
  if (!raw.trim()) return raw;
  var who = narrUserName() || '玩家角色';
  var lines;
  if (isLatest) {
    lines = [
      NARR_USR_OPEN,
      '「' + who + '」跟我是两回事，请勿混为一谈；「' + who + '」只是故事中的一个普通角色与视角镜头。',
      '如果你真的想让我满意，就请写出足够真实的世界——所有角色都有自己的生活轨迹、利益算计与人际关系网，绝不围绕「' + who + '」旋转。',
      '本回合我想让「' + who + '」尝试采取的行动是：',
      NARR_ACT_OPEN,
      raw,
      NARR_ACT_CLOSE,
      lethal
        ? ('以上仅代表「' + who + '」的单方主观意图与尝试，随时可以被在场角色打断、拒绝、反制或无视；本世界没有主角免死光环，若「' + who + '」判断失误或贸然涉险，重伤乃至死亡都是自然且合理的真实结局。')
        : ('以上仅代表「' + who + '」的单方主观意图与尝试，随时可以被在场角色打断、拒绝、识破或无视，成败全由世界逻辑与客观实力裁定。'),
      NARR_USR_CLOSE
    ];
  } else {
    lines = [
      NARR_USR_OPEN,
      '上文回合「' + who + '」尝试采取的行动（仅作单方意图，可被他人打断或无视）：',
      NARR_ACT_OPEN,
      raw,
      NARR_ACT_CLOSE,
      NARR_USR_CLOSE
    ];
  }
  return lines.join('\n');
}

/* ---------------- 多协议消息读写（OpenAI / Claude / Gemini 原生） ---------------- */

function narrMsgList(body) {
  if (!body || typeof body !== 'object') return null;
  var root = (body.request && typeof body.request === 'object' && !Array.isArray(body.request)) ? body.request : body;
  if (Array.isArray(root.messages) && root.messages.length) return { arr: root.messages, proto: 'messages' };
  if (Array.isArray(root.contents) && root.contents.length) return { arr: root.contents, proto: 'contents' };
  return null;
}

function narrMsgIsUser(m, proto) {
  if (!m || typeof m !== 'object') return false;
  var r = String(m.role || '').toLowerCase();
  if (proto === 'contents') return r === 'user';
  return r === 'user';
}

function narrMsgText(m, proto) {
  if (!m || typeof m !== 'object') return '';
  if (proto === 'contents' || Array.isArray(m.parts)) {
    var ps = m.parts;
    if (!Array.isArray(ps)) return '';
    for (var i = 0; i < ps.length; i++) {
      var p = ps[i];
      if (p && typeof p.text === 'string' && !p.thought && !p.functionCall && !p.functionResponse) {
        return p.text;
      }
    }
    return '';
  }
  return String(textOfMsg(m) || '');
}

function narrSetMsgText(m, v, proto) {
  if (!m || typeof m !== 'object') return false;
  if (proto === 'contents' || Array.isArray(m.parts)) {
    var ps = m.parts;
    if (!Array.isArray(ps)) return false;
    for (var i = 0; i < ps.length; i++) {
      var p = ps[i];
      if (p && typeof p.text === 'string' && !p.thought && !p.functionCall && !p.functionResponse) {
        p.text = v;
        return true;
      }
    }
    return false;
  }
  setMsgText(m, v);
  return true;
}

/* 收集整个请求体中（剔除我们自己的 AR-NAR/AR-USR 后）的预设文本，供「礼让预设」探测重复条目 */
function narrCollectPresetText(body) {
  var chunks = [];
  try {
    var root = (body && body.request && typeof body.request === 'object' && !Array.isArray(body.request)) ? body.request : body;
    if (!root || typeof root !== 'object') return '';
    if (typeof root.system === 'string') chunks.push(root.system);
    else if (Array.isArray(root.system)) {
      for (var si = 0; si < root.system.length; si++) {
        if (root.system[si] && typeof root.system[si].text === 'string') chunks.push(root.system[si].text);
      }
    }
    if (root.systemInstruction && Array.isArray(root.systemInstruction.parts)) {
      for (var gi = 0; gi < root.systemInstruction.parts.length; gi++) {
        if (root.systemInstruction.parts[gi] && typeof root.systemInstruction.parts[gi].text === 'string') {
          chunks.push(root.systemInstruction.parts[gi].text);
        }
      }
    }
    if (root.system_instruction && Array.isArray(root.system_instruction.parts)) {
      for (var g2 = 0; g2 < root.system_instruction.parts.length; g2++) {
        if (root.system_instruction.parts[g2] && typeof root.system_instruction.parts[g2].text === 'string') {
          chunks.push(root.system_instruction.parts[g2].text);
        }
      }
    }
    var listInfo = narrMsgList(body);
    if (listInfo) {
      var arr = listInfo.arr;
      for (var i = 0; i < arr.length; i++) {
        var m = arr[i];
        if (!m) continue;
        var r = String(m.role || '').toLowerCase();
        if (r === 'assistant' || r === 'model') continue;
        var tx = narrStrip(narrMsgText(m, listInfo.proto));
        if (tx) chunks.push(tx);
      }
    }
  } catch (eC) {}
  return chunks.join('\n');
}

function narrPresetHasKnow(body) {
  try { return NARR_PRESET_KNOW_RE.test(narrCollectPresetText(body)); } catch (e) { return false; }
}
function narrPresetHasCharm(body) {
  try { return NARR_PRESET_CHARM_RE.test(narrCollectPresetText(body)); } catch (e) { return false; }
}

/* ---------------- 真玩家发言楼层识别（绝不误包预设伪 user 规则块） ---------------- */

function narrRecentChatUserTexts() {
  var out = [];
  try {
    var c = stCtx();
    var ch = c && Array.isArray(c.chat) ? c.chat : null;
    if (!ch || !ch.length) return out;
    for (var i = ch.length - 1; i >= 0 && out.length < 8; i--) {
      var it = ch[i];
      if (!it || !it.is_user || it.is_system) continue;
      var s = String(it.mes == null ? '' : it.mes).trim();
      if (s) out.push(s);
    }
  } catch (e) {}
  return out;
}

/* 光域预设玩家输入边界外壳：<lk_user_turn>（V0.1）与 <lk_current_input>/<lk_history_input>（V0.2）（真玩家楼层，绝非预设控制块） */
var NARR_USER_TURN_RE = /^\s*<(lk_(?:user_turn|current_input|history_input))(?:\s[^>]*)?>([\s\S]*?)<\/\1>\s*$/i;
function narrStripUserTurnShell(s) {
  var t = String(s == null ? '' : s).trim();
  var m = NARR_USER_TURN_RE.exec(t);
  return m ? String(m[2] || '').trim() : t;
}

function narrMatchesRecentChat(text, chatUsers) {
  if (!chatUsers || !chatUsers.length) return false;
  var t = String(text || '').trim();
  if (!t) return false;
  var inner = narrStripUserTurnShell(t);
  for (var i = 0; i < chatUsers.length; i++) {
    var cu = chatUsers[i];
    if (t === cu || (inner && inner === cu)) return true;
    /* 兼容酒馆前缀 "UserName: 正文" 或轻微前后裁剪 */
    if (cu.length >= 6 && t.indexOf(cu) >= 0 && t.length <= cu.length + 60) return true;
    if (t.length >= 6 && cu.indexOf(t) >= 0 && cu.length <= t.length + 60) return true;
    if (inner && cu.length >= 6 && inner.indexOf(cu) >= 0 && inner.length <= cu.length + 60) return true;
    if (inner && inner.length >= 6 && cu.indexOf(inner) >= 0 && cu.length <= inner.length + 60) return true;
  }
  return false;
}

function narrIsPresetControlUserMsg(cleanText, msg, chatUsers) {
  if (!msg) return true;
  if (typeof lkIsProtectedMsg === 'function' && lkIsProtectedMsg(msg)) return true;
  /* Gemini functionResponse / inlineData 保护 */
  if (Array.isArray(msg.parts)) {
    for (var pi = 0; pi < msg.parts.length; pi++) {
      var pp = msg.parts[pi];
      if (pp && (pp.functionResponse || pp.functionCall)) return true;
    }
  }
  var t = String(cleanText || '').trim();
  if (!t) return true;
  var isUserTurnWrapped = NARR_USER_TURN_RE.test(t);
  var checkTxt = isUserTurnWrapped ? narrStripUserTurnShell(t) : t;
  if (!checkTxt) return true;
  /* 若精准命中酒馆聊天记录里的真实玩家发言，直接放行（绝不误杀） */
  if (narrMatchesRecentChat(t, chatUsers) || (isUserTurnWrapped && narrMatchesRecentChat(checkTxt, chatUsers))) return false;
  if (!isUserTurnWrapped && NARR_CTRL_HEAD_RE.test(checkTxt)) return true;
  if (NARR_CTRL_BODY_RE.test(checkTxt)) return true;
  /* 孤立闭合标签或末尾挂有未闭合起笔开标签的预设预填桥接尾块 */
  if (!isUserTurnWrapped && /^<\/[a-zA-Z0-9_\u4e00-\u9fa5~-]+>\s*$/.test(checkTxt)) return true;
  var tailOpen = isUserTurnWrapped ? null : NARR_UNCLOSED_TAIL_TAG_RE.exec(checkTxt);
  if (tailOpen) {
    var tagNm = String(tailOpen[1] || '').toLowerCase();
    if (tagNm !== 'user' && tagNm !== 'char' && checkTxt.toLowerCase().indexOf('</' + tagNm + '>') < 0) return true;
  }
  /* 超长结构化 Markdown 规则清单（预设 system-in-user 典型形态） */
  if (checkTxt.length > 1400) {
    var ruleHits = checkTxt.match(/^(?:#{1,4}\s+|[-*]\s+.*(?:严禁|禁止|必须|规则|视角|格式|原则|准则))/gm);
    if (ruleHits && ruleHits.length >= 4) return true;
  }
  return false;
}

/* 剥离末尾已挂载的其它脚本/插件尾块（AR-TRUNC / AR-OOC / 外部导演卡 / 定时提醒），避免把它们误包进 <<<ACT>>> 或干扰真楼层匹配 */
function narrSplitExternalTails(s) {
  var core = String(s == null ? '' : s);
  var tails = [];
  var pairs = [
    ['〔AR-TRUNC', '〔/AR-TRUNC〕'],
    ['〔AR-OOC', '〔/AR-OOC〕'],
    ['<下轮导演卡>', '</下轮导演卡>'],
    ['<定时提醒>', '</定时提醒>'],
    ['<定时注入提示词>', '</定时注入提示词>']
  ];
  for (var guard = 0; guard < 8; guard++) {
    var cut = false;
    var trimmed = core.replace(/[ \t\r\n]+$/, '');
    for (var p = 0; p < pairs.length; p++) {
      var openMark = pairs[p][0], closeMark = pairs[p][1];
      if (trimmed.length >= closeMark.length && trimmed.slice(-closeMark.length) === closeMark) {
        var oi = (openMark === '〔AR-OOC') ? trimmed.indexOf(openMark) : trimmed.lastIndexOf(openMark);
        if (oi >= 0) {
          tails.unshift(trimmed.slice(oi));
          core = trimmed.slice(0, oi).replace(/[ \t\r\n]+$/, '');
          cut = true;
          break;
        }
      }
    }
    if (!cut) break;
  }
  return { core: core, tail: tails.join('\n\n') };
}

/* 返回按“从新到旧”排序的真实玩家 user 消息下标数组（depth 0, 1, 2...） */
function narrFindRealUserIndices(listInfo) {
  var arr = listInfo.arr, proto = listInfo.proto;
  var chatUsers = narrRecentChatUserTexts();
  var matchedChat = [];
  var real = [];
  var fallback = [];
  for (var i = arr.length - 1; i >= 0; i--) {
    var m = arr[i];
    if (!narrMsgIsUser(m, proto)) continue;
    if (typeof lkIsProtectedMsg === 'function' && lkIsProtectedMsg(m)) continue;
    var raw = narrMsgText(m, proto);
    var clean = narrStrip(raw);
    if (!clean.trim()) continue;
    fallback.push(i);
    var coreForMatch = (typeof narrSplitExternalTails === 'function') ? narrSplitExternalTails(clean).core : clean;
    if (chatUsers.length && (narrMatchesRecentChat(coreForMatch, chatUsers) || narrMatchesRecentChat(clean, chatUsers))) {
      matchedChat.push(i);
      real.push(i);
      continue;
    }
    if (!narrIsPresetControlUserMsg(clean, m, chatUsers)) {
      real.push(i);
    }
  }
  /* 若已通过 ST 聊天记录精确命中真实玩家楼层，则仅信任这些已核验楼层，彻底杜绝任何预设合成 user 块被误包 */
  if (matchedChat.length) return { real: matchedChat, fallback: fallback };
  return { real: real, fallback: fallback };
}

/* ---------------- 主注入入口（只改传入的 body 副本） ---------------- */

function narrApply(body) {
  var out = [];
  NARR_RT.yieldKnow = false;
  NARR_RT.yieldCharm = false;
  NARR_RT.wrappedCount = 0;
  NARR_RT.lastMode = '';

  if (!body || typeof body !== 'object') return out;
  var listInfo = narrMsgList(body);
  if (!listInfo || !listInfo.arr.length) return out;
  var arr = listInfo.arr, proto = listInfo.proto;

  /* 1) 先把所有 user 消息上的旧 AR-NAR / AR-USR 块剥净还原（保证幂等 + 关闭开关时彻底清干净） */
  var hadAnyOld = false;
  var cleanedAny = false;
  for (var c0 = 0; c0 < arr.length; c0++) {
    var mc = arr[c0];
    if (!narrMsgIsUser(mc, proto)) continue;
    var old0 = narrMsgText(mc, proto);
    if (old0.indexOf('〔' + NARR_TAG) >= 0 || old0.indexOf('〔' + NARR_USR_TAG) >= 0) {
      hadAnyOld = true;
      var base0 = narrStrip(old0);
      if (base0 !== old0) {
        narrSetMsgText(mc, base0, proto);
        cleanedAny = true;
      }
    }
  }

  /* 2) 非故事元模式避让 & 「预设适配 = 礼让预设」单维避重 */
  var presetTextAll = narrCollectPresetText(body);
  if (NARR_META_MODE_RE.test(presetTextAll)) {
    if (cleanedAny) out.push('叙述:清掉');
    else out.push('叙述:元模式避让');
    return out;
  }
  var forceMode = (typeof presetCompatForce === 'function') ? presetCompatForce() : true;
  var wantKnow = narrPick(cfg && cfg.know) !== 'off';
  var wantCharm = narrPick(cfg && cfg.charm) !== 'off';
  var skipKnow = false, skipCharm = false;
  if (!forceMode) {
    /* 双生协议防死锁：《光域·镜界》的独立防线 base_standalone_guard 已让位给卢克时，不被其思维链清单词误判为需要礼让 */
    var prismHandedToLuke = false;
    try {
      if (typeof isPrismPresetActive === 'function' && isPrismPresetActive()) {
        var pSnap = (typeof prismCollectSnapshot === 'function') ? prismCollectSnapshot() : null;
        if (!pSnap || !pSnap.enabledMap || !pSnap.enabledMap.base_standalone_guard) {
          prismHandedToLuke = true;
        }
      }
    } catch (ePrY) {}
    if (!prismHandedToLuke) {
      if (wantKnow && NARR_PRESET_KNOW_RE.test(presetTextAll)) { skipKnow = true; NARR_RT.yieldKnow = true; }
      if (wantCharm && NARR_PRESET_CHARM_RE.test(presetTextAll)) { skipCharm = true; NARR_RT.yieldCharm = true; }
    }
  }

  var block = narrBody({ skipKnow: skipKnow, skipCharm: skipCharm, skipLethal: skipCharm });
  var doWrap = !skipCharm && narrCharmWrapOn();
  var lethal = !skipCharm && narrCharmLethalOn();

  if (!block && !doWrap) {
    if (cleanedAny) out.push('叙述:清掉');
    else if (skipKnow || skipCharm) out.push('叙述:礼让预设');
    return out;
  }

  /* 3) 定位真实玩家 user 楼层 */
  var found = narrFindRealUserIndices(listInfo);
  var wrapIdxs = [];
  if (doWrap && found.real.length) {
    var maxWrap = NARR_WRAP_MAX_DEPTH + 1;
    for (var wi = 0; wi < found.real.length && wi < maxWrap; wi++) {
      wrapIdxs.push(found.real[wi]);
    }
  }

  /* 规则块落点：优先最新真实玩家 user；若全部都是合成/规则消息，兜底落到最后一条非受保护 user */
  var ruleIdx = found.real.length ? found.real[0] : (found.fallback.length ? found.fallback[0] : -1);

  /* 4) 执行近 2 轮三明治贴脸包裹（depth 0 全量，depth 1~2 轻量） */
  var wrappedN = 0;
  var savedTails = {};
  for (var wj = 0; wj < wrapIdxs.length; wj++) {
    var idxW = wrapIdxs[wj];
    var mW = arr[idxW];
    var baseW = narrMsgText(mW, proto);
    if (!baseW.trim()) continue;
    var spW = narrSplitExternalTails(baseW);
    if (!spW.core.trim()) continue;
    if (spW.tail) savedTails[idxW] = spW.tail;
    var wrappedTxt = narrWrapUserText(spW.core, wj === 0, lethal);
    var finalW = wrappedTxt;
    if (spW.tail && idxW !== ruleIdx) finalW += '\n\n' + spW.tail;
    if (finalW !== baseW) {
      narrSetMsgText(mW, finalW, proto);
      wrappedN++;
    }
  }
  NARR_RT.wrappedCount = wrappedN;

  /* 5) 执行规则块注入（紧跟在末条玩家消息末尾，位于外部尾块 AR-TRUNC / AR-OOC 之前） */
  var wroteRule = false;
  if (ruleIdx >= 0) {
    var mR = arr[ruleIdx];
    var curR = narrMsgText(mR, proto);
    var ruleTail = savedTails[ruleIdx] || '';
    if (!ruleTail) {
      var spR = narrSplitExternalTails(curR);
      if (spR.tail) { curR = spR.core; ruleTail = spR.tail; }
    }
    var nextR = curR;
    if (block) {
      var sep = '';
      if (nextR) sep = /\n$/.test(nextR) ? '\n' : '\n\n';
      nextR = nextR + sep + block;
      wroteRule = true;
    }
    if (ruleTail) nextR = nextR + (nextR ? '\n\n' : '') + ruleTail;
    if (nextR !== narrMsgText(mR, proto)) {
      narrSetMsgText(mR, nextR, proto);
    }
  }

  if (wroteRule || wrappedN > 0) {
    var tags = [];
    if (!skipKnow && wantKnow) tags.push('防全知' + narrTag(cfg.know));
    if (!skipCharm && wantCharm) {
      var ct = '去媚' + narrTag(cfg.charm);
      if (wrappedN > 0) ct += '·包裹' + wrappedN;
      if (lethal) ct += '·致命';
      tags.push(ct);
    }
    var lbl = tags.join('+') || narrLabel();
    NARR_RT.lastMode = lbl;
    out.push('叙述:' + lbl);
  } else if (hadAnyOld && cleanedAny) {
    out.push('叙述:清掉');
  }
  return out;
}

/* ===== 15_ooc.js ===== */
/* 15_ooc.js — v0.76 反 OOC：点名 / 反模板 / 变更门槛 / 口吻一致
 *
 * 四件事，四个开关，各管各的：
 *   点名      —— 先认出这一轮在场的是谁，再让他们各自对照世界书；
 *   反模板    —— 同一类情绪别用现成的动作包（眼底闪过、嘴角勾起…）；
 *   变更门槛  —— 态度 / 关系 / 立场变了，要指得出是哪件事改的；
 *   口吻一致  —— 说话方式、称呼、口癖跟前文一致（换人检验）。
 *
 * 三条不变量（与 12_narr.js 同）：
 *   1) 预设只读：这里只决定自己注不注，从不删改请求体里预设的任何内容；
 *   2) 幂等：注入前先剥掉上一次的块，注一次和注十次结果完全一样；
 *   3) 失败安全：任何一步抛错都退化成「什么都不注」，绝不让它弄坏正常请求。
 *
 * 注入通道：优先酒馆自己的扩展提示位（setExtensionPrompt，IN_CHAT / depth 4）；
 * 宿主没有这个方法时回落成「贴末条 user 消息尾部」，与叙述层同一位置。
 *   ★ 扩展提示位是宿主持久保存的：写进去之后由宿主自己在下一轮拼提示时带上，
 *     所以这条路径不改请求体、也不会和回落路径同时生效（oocApply 返回 true 时
 *     planRequest 不会再调 oocBodyPatch）。
 *
 * 世界书：只读 ctx.characters[this_chid].data.extensions.world → loadWorldInfo(book)。
 *   loadWorldInfo 在部分版本上是 Promise，这里只吃同步返回值；拿到 Promise 就当
 *   拿不到（宁可这一轮不点名，也不把请求挂死）。
 */

var OOC_TAG = '〔AR-OOC 1.0〕';
var OOC_CLOSE = '〔/AR-OOC〕';
var OOC_KEY = 'ar6.ooc';
var OOC_ITEMS = ['roll', 'tpl', 'chg', 'voice'];
var OOC_CFGKEY = { roll: 'oocRoll', tpl: 'oocTpl', chg: 'oocChg', voice: 'oocVoice' };
var OOC_LABEL = { roll: '点名', tpl: '反模板', chg: '变更门槛', voice: '口吻一致' };

/* ---------------- 文案 ----------------
   四段各自成块，各自带同一个头（OOC_TAG），中间空一行。
   面板预览与注入用的是同一份文案，不许只改一边：
   改一个字，用户面板上看到的和这里给的就不是同一份东西了。
   {{user}} 原样保留，输出前由 oocFill() 换成真名（拿不到就换「你」）。 */
var OOC_SEG_TPL = OOC_TAG + '\n' +
  '同一类情绪，不要用现成的动作包打发——眼底闪过、嘴角勾起、喉结滚动、\n' +
  '呼吸一滞、身子一僵，这类动作谁都能做，写了等于没写。\n' +
  '\n' +
  '不要用一句话概括一个人的全部性格，也不要让他只当「那个温柔的人」。\n' +
  '\n' +
  '他做的动作，得是这个人做得出来的动作。';

var OOC_SEG_CHG = OOC_TAG + '\n' +
  '一个人对另一个人的态度、关系、立场变了，要指得出是哪件事改变的、中间经过什么。\n' +
  '\n' +
  '说不出缘由的变化，不要写。';

var OOC_SEG_VOICE = OOC_TAG + '\n' +
  '他的说话方式、称呼、口癖、句子长短，跟前文保持一致。\n' +
  '\n' +
  '检验方法：把这句话换给另一个人说，如果照样成立，那就是写错了，重写。';

/* 点名：名单由调用方拼，「、」连接 + 「。」 */
function oocRollSeg(names) {
  var list = String((names || []).join('、')).replace(/[、\s]+$/, '');
  return OOC_TAG + '\n' +
    '本轮涉及的角色：' + list + '。\n' +
    '\n' +
    '动笔前，逐一对照世界书里他们各自的条目——\n' +
    '他怎么说话、对{{user}}是什么态度、什么事他不会做。\n' +
    '\n' +
    '世界书写了的，以世界书为准；世界书没写的，按前文已经写过的演，不要改。';
}

/* ---------------- 配置 ---------------- */

function oocFlag(v, dflt) {
  if (v === undefined || v === null) return dflt;
  return !!v;
}

/* 总闸关 → 返回 null（调用方一律当「什么都不做」）。
   注意：读的是 cfg 里的存值；CFG_DEFAULT 的默认值是 off，迁移不重跑。 */
function oocCfg() {
  var c = (cfg && typeof cfg === 'object') ? cfg : null;
  if (!c) return null;
  if (String(c.ooc == null ? 'off' : c.ooc) !== 'on') return null;
  return {
    roll: oocFlag(c.oocRoll, true),
    tpl: oocFlag(c.oocTpl, true),
    chg: oocFlag(c.oocChg, false),
    voice: oocFlag(c.oocVoice, true)
  };
}

/* 单项是否开着（面板渲染用；总闸关时一律当关） */
function oocOnOf(item) {
  var c = oocCfg();
  if (!c) return false;
  return !!c[item];
}

/* ---------------- 宿主上下文（老 ST 可能什么都没有） ---------------- */

function oocCtx() {
  try {
    if (typeof stCtx === 'function') {
      var c = stCtx();
      if (c) return c;
    }
  } catch (e0) {}
  try {
    var st = (typeof HOST !== 'undefined' && HOST) ? HOST.SillyTavern : null;
    if (st && typeof st.getContext === 'function') return st.getContext();
  } catch (e1) {}
  return null;
}

/* 这个角色绑的世界书名；没绑返回空串 */
function oocBook() {
  try {
    var c = oocCtx();
    if (!c) return '';
    var list = c.characters;
    var id = c.this_chid;
    if (list == null || id == null || id === '') return '';
    var n = +id;
    if (!isFinite(n) || n < 0) return '';
    var ch = list[n];
    if (!ch) return '';
    var d = ch.data;
    var ext = d && d.extensions;
    var w = ext && ext.world;
    return String(w == null ? '' : w).trim();
  } catch (e) { return ''; }
}

/* 世界书条目 → 人物名单。只认两种写法：
   P1  comment 带 [角色] / [人物] / [NPC] … 前缀；
   P2  comment 本身就是 2~6 字的纯名字，且每个 key 也都是 2~6 字纯名字。 */
var OOC_NAME_RE = /^[\u4e00-\u9fa5A-Za-z·]{2,6}$/;
var OOC_P1_RE = /^\[(角色|人物|NPC|npc|char|Char)\]\s*/;

function oocTrim(s) {
  return String(s == null ? '' : s).replace(/^[\s\u3000]+|[\s\u3000]+$/g, '');
}

function oocKeys(e) {
  var out = [];
  if (!e || !Array.isArray(e.key)) return out;
  for (var i = 0; i < e.key.length; i++) {
    var k = oocTrim(e.key[i]);
    if (!k) continue;
    if (out.indexOf(k) < 0) out.push(k);
  }
  return out;
}

/* 世界书数据的同步缓存。
   新版酒馆的 ctx.loadWorldInfo 返回 Promise，同步路径拿不到；这里把 Promise
   的结果回填进来，下一次渲染 / 下一轮请求就能用（TTL 30 秒，改完世界书不用刷新）。
   key 是书名；只缓存成功解析过的整本数据。 */
var OOC_BOOK_CACHE = {};
var OOC_BOOK_WAIT = {};
var OOC_BOOK_TTL = 30000;

function oocBookCached(book, c) {
  var hit = OOC_BOOK_CACHE[book];
  if (hit) {
    if ((Date.now() - hit.at) < OOC_BOOK_TTL) return hit.data;
    delete OOC_BOOK_CACHE[book];
  }
  var data;
  try { data = c.loadWorldInfo(book); } catch (e0) { return null; }
  if (data && typeof data.then === 'function') {
    /* Promise 不认识，也没法在这里 await —— 挂一次 then 回填，这一轮先当拿不到 */
    if (!OOC_BOOK_WAIT[book]) {
      OOC_BOOK_WAIT[book] = 1;
      try {
        data.then(function (d) {
          delete OOC_BOOK_WAIT[book];
          if (d && typeof d === 'object') OOC_BOOK_CACHE[book] = { data: d, at: Date.now() };
        }, function () { delete OOC_BOOK_WAIT[book]; });
      } catch (e1) { delete OOC_BOOK_WAIT[book]; }
    }
    return null;
  }
  if (!data || typeof data !== 'object') return null;
  return data;
}

function oocPeople(bookName) {
  var out = [];
  var book = oocTrim(bookName);
  if (!book) return out;
  var c = oocCtx();
  if (!c || typeof c.loadWorldInfo !== 'function') return out;
  var data = oocBookCached(book, c);
  if (!data) return out;
  var ent = data.entries;
  if (!ent || typeof ent !== 'object') return out;

  var seen = {};
  var i, e, cm, nm, keys, m;
  var uids = [];
  if (Array.isArray(ent)) {
    for (i = 0; i < ent.length; i++) uids.push(i);
  } else {
    for (var k in ent) if (Object.prototype.hasOwnProperty.call(ent, k)) uids.push(k);
  }

  for (i = 0; i < uids.length && out.length < 40; i++) {
    e = ent[uids[i]];
    if (!e || typeof e !== 'object') continue;
    if (e.disable === true) continue;
    cm = oocTrim(e.comment);
    if (!cm) continue;
    nm = '';
    keys = oocKeys(e);
    m = OOC_P1_RE.exec(cm);
    if (m) {
      nm = oocTrim(cm.slice(m[0].length));
      if (!nm) continue;
    } else if (OOC_NAME_RE.test(cm) && keys.length) {
      var ok = true;
      for (var j = 0; j < keys.length; j++) {
        if (!OOC_NAME_RE.test(keys[j])) { ok = false; break; }
      }
      if (!ok) continue;
      nm = cm;
    } else {
      continue;
    }
    if (seen[nm]) continue;
    seen[nm] = 1;
    out.push({ name: nm, keys: keys });
  }
  return out;
}

/* 在场：按 key 在最近两条消息里出现几次排序，取前 6。
   次数相同按世界书里的先后，保证同一段对话里名单稳定。 */
function oocPresent(people, text) {
  var out = [];
  if (!people || !people.length) return out;
  var t = String(text == null ? '' : text);
  if (!t) return out;
  var hit = [];
  for (var i = 0; i < people.length; i++) {
    var p = people[i];
    if (!p) continue;
    var ks = p.keys || [];
    var n = 0;
    for (var j = 0; j < ks.length; j++) {
      var k = String(ks[j] == null ? '' : ks[j]);
      if (!k) continue;
      var at = t.indexOf(k);
      while (at >= 0) {
        n++;
        at = t.indexOf(k, at + k.length);
        if (n > 99) break;
      }
    }
    if (n > 0) hit.push({ name: String(p.name || ''), n: n, i: i });
  }
  if (!hit.length) return out;
  hit.sort(function (a, b) { return (b.n - a.n) || (a.i - b.i); });
  for (var q = 0; q < hit.length && q < 6; q++) out.push(hit[q].name);
  return out;
}

/* 最近两条消息的正文；ctx.chat 不可用时返回空串 */
function oocRecent() {
  try {
    var c = oocCtx();
    if (!c) return '';
    var ch = c.chat;
    if (!ch || !ch.length) return '';
    var from = ch.length - 2;
    if (from < 0) from = 0;
    var parts = [];
    for (var i = from; i < ch.length; i++) {
      var m = ch[i];
      if (!m) continue;
      parts.push(String(m.mes == null ? '' : m.mes));
    }
    return parts.join('\n');
  } catch (e) { return ''; }
}

/* ---------------- 冲突选项（只在本会话内，不落配置） ----------------
   'script' = 用我们的；'preset' = 听预设的（这一段就不注了）。 */
var OOC_CHOICE = {};

function oocChoice(item) {
  var v = OOC_CHOICE[String(item == null ? '' : item)];
  return (v === 'script' || v === 'preset') ? v : '';
}

function oocSetChoice(item, v) {
  var k = String(item == null ? '' : item);
  if (OOC_ITEMS.indexOf(k) < 0) return '';
  if (v !== 'script' && v !== 'preset') { delete OOC_CHOICE[k]; return ''; }
  OOC_CHOICE[k] = v;
  return v;
}

function oocResetChoice() {
  for (var i = 0; i < OOC_ITEMS.length; i++) delete OOC_CHOICE[OOC_ITEMS[i]];
}

/* ---------------- 拼接 ---------------- */

/* {{user}} → 真名（拿不到就用「你」）。这里不碰尖括号，文案里也没有 <user>。 */
function oocFill(t) {
  var s = String(t == null ? '' : t);
  if (s.indexOf('{{user}}') < 0) return s;
  var n = '';
  try { if (typeof narrUserName === 'function') n = narrUserName(); } catch (e) {}
  return s.split('{{user}}').join(n || '你');
}

/* 这一轮要注的整块；总闸关 / 四项全关时返回空串 */
function oocText() {
  var c = oocCfg();
  if (!c) return '';
  var parts = [];

  /* 先算「这一轮提到了谁」。世界书里一个人物都认不出来时不做拦截
     （可能是没绑世界书，不能因此把功能关掉）；但只要认得出人物、
     而最近两条消息里一个都没提到，就整块不注——没人在场的时候
     跟模型讲「别写 OOC」只是噪音，还白花 token。 */
  var names = [];
  var known = 0;
  try {
    var book = oocBook();
    if (book) {
      var people = oocPeople(book);
      known = people.length;
      if (known) names = oocPresent(people, oocRecent());
    }
  } catch (e0) { names = []; known = 0; }
  if (known > 0 && !names.length) return '';

  /* 1) 点名：认不出人就不注这一段（写「本轮涉及的角色：。」没有意义） */
  if (c.roll && oocChoice('roll') !== 'preset') {
    if (names.length) parts.push(oocFill(oocRollSeg(names)));
  }

  /* 2~4) 反模板 → 变更门槛 → 口吻一致（顺序固定，别按开关顺序拼） */
  if (c.tpl && oocChoice('tpl') !== 'preset') parts.push(oocFill(OOC_SEG_TPL));
  if (c.chg && oocChoice('chg') !== 'preset') parts.push(oocFill(OOC_SEG_CHG));
  if (c.voice && oocChoice('voice') !== 'preset') parts.push(oocFill(OOC_SEG_VOICE));

  return parts.length ? (parts.join('\n\n') + '\n' + OOC_CLOSE) : '';
}

/* 粗估 token（中文约 0.7 tok/字），只给面板一个量级 */
function oocTokens() {
  var t = '';
  try { t = oocText(); } catch (e) { t = ''; }
  return t ? Math.round(t.length * 0.7) : 0;
}

function oocLabel() {
  var c = oocCfg();
  if (!c) return '关';
  var out = [];
  for (var i = 0; i < OOC_ITEMS.length; i++) {
    var k = OOC_ITEMS[i];
    if (!c[k] || oocChoice(k) === 'preset') continue;
    out.push(OOC_LABEL[k]);
  }
  return out.length ? out.join('+') : '关';
}

/* ---------------- 注入 ---------------- */

/* 剥掉上一次注入的块。
   我们的块永远是整块贴在尾部（四段各带同一个头，块内没有别人的东西），
   所以从第一个标记砍到结尾即可；剥完把尾部空白收掉，免得每轮多一行空行。 */
function oocStrip(s) {
  var t = String(s == null ? '' : s);
  var i = t.indexOf(OOC_TAG);
  if (i < 0) return t;
  var j = t.indexOf(OOC_CLOSE, i);
  if (j < 0) return t.slice(0, i).replace(/[ \t\r\n]+$/, '');
  var head = t.slice(0, i).replace(/[ \t\r\n]+$/, '');
  var tail = t.slice(j + OOC_CLOSE.length).replace(/^[ \t\r\n]+/, '');
  if (!tail) return head;
  return head + (head ? '\n\n' : '') + tail;
}

/* 扩展提示位通道：拿得到 ctx 且它真的有 setExtensionPrompt 才算 */
function oocChannel() {
  try {
    var c = oocCtx();
    if (c && typeof c.setExtensionPrompt === 'function') return c;
  } catch (e) {}
  return null;
}

/* 写扩展提示位。true = 这一次走的就是这条通道；false = 交给 oocBodyPatch 回落。
   文本为空时写空串，等于把上一轮留下的块清掉（不然关掉总闸之后它还在）。 */
function oocApply() {
  var text = '';
  try { text = oocText(); } catch (e0) { text = ''; }
  var c = oocChannel();
  if (!c) return false;
  try {
    c.setExtensionPrompt(OOC_KEY, text, 1, 4, false, 0);
    return true;
  } catch (e1) { return false; }
}

/* 回落通道：贴到最后一条 role==='user' 的 content 尾部（与 narrApply 同一位置）。
   只改传进来的 body 副本，聊天记录一个字节都不动。
   返回改动描述数组，调用方必须 push 到 out.changed，否则不会序列化。 */
function oocBodyPatch(body) {
