}

/* 本地确定性预编码（默认 core 精准硬红线词模式不误伤常规小说词，all 模式启用全量 894 词；成年年龄守卫 + ASCII 词边界 + 跳过 ⟦LK_KEEP_N⟧） */
var SUBAPI_KEEP_SPLIT_RE = /(\u27E6LK_KEEP_\d+\u27E7)/g;
function subApiLexEncode(maskedText, opt) {
