    if (wGi.hits > 0) { root.systemInstruction = wGi.text; hits += wGi.hits; msgs++; }
  } else if (root.systemInstruction && Array.isArray(root.systemInstruction.parts)) {
    for (var gi = 0; gi < root.systemInstruction.parts.length; gi++) {
