    if (tripped || nextIdx >= taskFns.length) return Promise.resolve();
    if ((Date.now() - startAt) >= budgetMs) { tripped = true; return Promise.resolve(); }
    var myIdx = nextIdx++;
    return Promise.resolve().then(function () {
      return taskFns[myIdx]();
    }).then(function (val) {
