      if (!cadenceWhy && noHardProof && rec) {
        try {
          if (typeof shapeJudge === 'function') {
            var sj = shapeJudge(rec);
            if (sj && sj.line && !hasThink) {
              cadenceWhy = '回包结构突变：' + sj.line;
            }
