    }

    /* unknown / echo：如果带有 thoughtSignature 或原生硬证仍给 V2，否则给 V2(无模型名) */
    out.grade = (hasThoughtSig || hasNativeMV) ? 'V2' : 'V2';
    out.summary = (code === 'echo') ? '渠道仅回显模型名，无可用身份硬证' : '上游未回传模型标识（建议点「真伪探针」复核）';
  } catch (e) {}
  return out;
}

