  }
  /* 常见简写兜底 */
  if (/gemini[-_. ]?4[-_. ]?h|4h\b/i.test(nm)) return 'G4H';
  if (/gemini[-_. ]?4[-_. ]?a|4a\b/i.test(nm)) return 'G4A';
