  var m = /LK\d{2}[STD]-[A-Z]{3}[0-9A-Z]{4}-[^-\s]+-V[0-4]F[0-9A-F]{2}-T\d+R\d+K(?:\d+|U)-E[0-9A-Z]{2,4}-[0-9A-Z]{4}/i.exec(txt);
