    var syncBtn = function () {
      try {
        var b = node.querySelector && node.querySelector('[data-ar6-nm="agree"]');
        if (!b) return;
        var lck = !!(NOTICE_MODAL.forced && NOTICE_MODAL.waitLeft > 0);
