        g.gain.setValueAtTime(0.001, t + 0.68);
        g.gain.linearRampToValueAtTime(0.09, t + 0.92);
        g.gain.exponentialRampToValueAtTime(0.001, t + 2.1);
        o.connect(g); ar6AudioRoute(g, 0.82);
