function pvpStatus() {
  if (!pvpOn()) return '';
  if (!cfg.enabled) return '⚠ 防护总开关关着：不会重发';
  if (cfg.safe) return '⚠ 安全模式开着：不重发、不补';
  if (pvpPaused()) return '⏸ 已暂停：自动重发停手（点「已暂停」恢复；手动补一次不受影响）';
  if (pvpManual()) return '🖐 手动模式：只在点「重试一次」时补，不会自动重发';
