  '#ar6-root .ar6-hint{margin:10px 12px 0;padding:9px 11px;border-radius:10px;font-size:11.8px;line-height:1.58;color:#CBD5E1;background:rgba(12,45,72,.45);border:1px solid rgba(56,189,248,.28);}',
