  '#ar6-root .ar6-temple-btn.noa.on .ar6-temple-ico{background:linear-gradient(135deg,#0F172A,#1E3A5F);border-color:#38BDF8;box-shadow:0 0 12px rgba(56,189,248,.55);}',
