    '<span class="ar6-lwm">' + esc(meta) + '</span>' +
    (r && r.routeHit ? '<span class="ar6-lwm" style="color:#e3b341">服务模型：' +
      esc(String(r.served || '?')) + '（和请求里的对不上）</span>' : '') +
    '</button>';
}

