      '|head=' + (hd ? hd.offsetHeight : '?') +
      '|vh=' + (HOST.innerHeight || 0) + '|vv=' + Math.round(vv) +
      '|fit=' + (vv && b.bottom <= vv + 2 ? 'yes' : 'NO');
  } catch (e) { return 'err:' + (e && e.message ? e.message : e); }
}


